# -*- coding: utf-8 -*-
u"""คลังข้อสอบหลังมิดเทอม เน้นแนวคิด · ใช้คู่กับ tools/adv-quiz2.py

หลักในการเขียน
  ถามว่าเข้าใจหลักหรือไม่ ไม่ใช่แทนค่าในสูตร
  ทุกข้อตอบได้โดยไม่ต้องกดเครื่องคิดเลข
  ตัวลวงสร้างจากความเข้าใจผิดที่เกิดขึ้นจริง ไม่ใช่ตัวเลือกที่ผิดอย่างเห็นได้ชัด
  คำอธิบายบอกทั้งว่าทำไมข้อที่ถูกถึงถูก และทำไมตัวลวงถึงน่าหลงเชื่อ

ch ที่ใส่คือเลขบทตามที่แสดงบนหน้าเว็บ คือ 6 ถึง 10
"""

QUIZ2 = u"""    {ch:6, q:'เหตุผลเชิงแนวคิดข้อใดอธิบายได้ดีที่สุดว่าทำไม TFRS 10 จึงยอมให้ส่วนได้เสียที่ไม่มีอำนาจควบคุมติดลบได้',
     o:['งบการเงินรวมมอง NCI เป็นส่วนหนึ่งของส่วนของเจ้าของตามทฤษฎีความเป็นหน่วยงาน ไม่ใช่หนี้สิน','NCI เป็นหนี้สินของกลุ่ม จึงติดลบได้เหมือนหนี้สินทั่วไป','เพราะผู้ถือหุ้นส่วนน้อยต้องรับผิดในหนี้ของบริษัทย่อยไม่จำกัดจำนวน','เพราะมาตรฐานต้องการให้กำไรของบริษัทใหญ่สูงที่สุดเท่าที่จะทำได้'], a:0,
     e:'งบรวมยืนอยู่บนทฤษฎีความเป็นหน่วยงาน ซึ่งมองกลุ่มเป็นหน่วยเศรษฐกิจเดียวและมอง NCI เป็นเจ้าของกลุ่มคนหนึ่ง เมื่อกลุ่มขาดทุน เจ้าของทุกคนก็ต้องรับไปตามส่วน · ถ้าหยุดที่ศูนย์ ขาดทุนส่วนที่เหลือจะถูกผลักไปให้บริษัทใหญ่คนเดียวทั้งที่ผลการดำเนินงานของกลุ่มไม่ได้เปลี่ยน · และข้อที่ว่า NCI เป็นหนี้สินนั้นผิด เพราะ NCI แสดงในส่วนของเจ้าของเสมอ'},
    {ch:6, q:'บริษัทย่อยกับบริษัทร่วมขาดทุนหนักเหมือนกัน แต่มาตรฐานให้ทำคนละอย่าง ความต่างนี้มาจากอะไรเป็นหลัก',
     o:['ระดับอำนาจที่ผู้ลงทุนมี ควบคุมได้จึงรับขาดทุนเต็ม ส่วนมีแค่อิทธิพลจึงจำกัดความรับผิดไว้แค่เงินที่ลงไป','ขนาดของสัดส่วนการถือหุ้นที่ต่างกัน','บริษัทย่อยใช้ TFRS ส่วนบริษัทร่วมใช้ TAS จึงต้องต่างกัน','บริษัทร่วมไม่ได้อยู่ในกลุ่มกิจการ จึงไม่ต้องรับรู้ขาดทุนใด ๆ'], a:0,
     e:'บริษัทย่อยถูกนำมารวมงบบรรทัดต่อบรรทัดเพราะเราควบคุมได้ จึงรับผลการดำเนินงานไปทั้งหมด · ส่วนบริษัทร่วมเรามีแค่อิทธิพล ไม่มีภาระต้องรับผิดชอบหนี้สินเกินกว่าเงินที่ลงไป การบันทึกขาดทุนต่อจึงเท่ากับรับรู้ภาระที่ไม่มีอยู่จริง ซึ่งขัดกับนิยามของหนี้สิน'},
    {ch:6, q:'เมื่อหยุดรับรู้ส่วนแบ่งขาดทุนในบริษัทร่วมแล้ว ขาดทุนส่วนที่เกินไปอยู่ที่ไหน',
     o:['พักไว้นอกบัญชี ต้องจดไว้เองเพื่อนำมาหักก่อนในปีที่บริษัทร่วมกลับมามีกำไร','หายไปเลย ไม่ต้องสนใจอีก','บันทึกเป็นหนี้สินทันทีทุกกรณี','โอนไปให้บริษัทย่อยอื่นในกลุ่มรับแทน'], a:0,
     e:'ย่อหน้า 38 ให้หยุดรับรู้ แต่ไม่ได้แปลว่าลืมได้ · ยอดนั้นถูกพักไว้นอกบัญชีและต้องนำมาหักก่อนในปีที่กลับมามีกำไร ตามย่อหน้า 39 · ส่วนการตั้งหนี้สินจะทำก็ต่อเมื่อมีภาระผูกพันตามกฎหมาย ภาระผูกพันจากการอนุมาน หรือได้จ่ายเงินแทนไปแล้วเท่านั้น ไม่ใช่ทุกกรณี'},
    {ch:6, q:'ในการคำนวณยอดขาดทุนที่พักไว้ของบริษัทร่วม ค่าตัดจำหน่ายส่วนที่ตีราคาเพิ่ม ณ วันซื้อ ต้องปฏิบัติอย่างไร',
     o:['ต้องเข้าคิวรออยู่ในยอดพักด้วย เพราะเป็นส่วนหนึ่งของการปรับส่วนแบ่งกำไรขาดทุน','ไม่เกี่ยวข้อง ให้รับรู้เป็นค่าใช้จ่ายทันทีทุกปี','ให้หยุดตัดจำหน่ายทันทีที่เงินลงทุนเหลือศูนย์','ให้นำไปลดค่าความนิยมแทน'], a:0,
     e:'ค่าตัดจำหน่ายส่วนที่ตีเพิ่มเป็นส่วนหนึ่งของการปรับส่วนแบ่งกำไรขาดทุนตามวิธีส่วนได้เสีย ไม่ใช่รายการแยกต่างหาก เมื่อหยุดรับรู้ส่วนแบ่งขาดทุน ตัวนี้ก็ต้องถูกพักไว้ด้วย · เป็นจุดที่คนคำนวณพลาดบ่อยที่สุดของเรื่องนี้ เพราะมักมองข้ามไปคิดแต่ส่วนแบ่งขาดทุนก้อนใหญ่'},
    {ch:6, q:'ถ้าปีถัดไปบริษัทย่อยที่เคยทำให้ NCI ติดลบกลับมามีกำไร ต้องทำอย่างไรกับยอดติดลบนั้น',
     o:['ไม่ต้องทำอะไรเป็นพิเศษ ส่วนแบ่งกำไรตามสัดส่วนปกติจะทยอยกลบยอดติดลบขึ้นมาเอง','ต้องให้บริษัทใหญ่คืนกำไรที่เคยรับเกินไปก่อน','ต้องปรับย้อนหลังงบปีก่อนให้ NCI เป็นศูนย์','ต้องรอจน NCI เป็นบวกก่อนจึงจะปันส่วนกำไรได้'], a:0,
     e:'กลไกนี้เรียบง่ายมากและเป็นเหตุผลหนึ่งที่มาตรฐานยอมให้ติดลบ · เมื่อบริษัทย่อยกลับมามีกำไร NCI รับส่วนแบ่งตามสัดส่วนเดิม ยอดติดลบจึงถูกกลบขึ้นมาเองโดยไม่ต้องมีกลไกพิเศษหรือการปรับย้อนหลังใด ๆ'},
    {ch:6, q:'ในกระดาษทำการกรณีขาดทุน ขาดทุนของบริษัทย่อยที่นำมาปันส่วนให้บริษัทใหญ่กับ NCI คือจำนวนใด',
     o:['ขาดทุนหลังปรับรายการตัดบัญชีแล้ว','ขาดทุนสุทธิตามงบของบริษัทย่อยก่อนปรับใด ๆ','ขาดทุนสุทธิบวกค่าตัดจำหน่ายส่วนที่ตีเพิ่ม','ขาดทุนสุทธิคูณสัดส่วนการถือหุ้นของบริษัทใหญ่'], a:0,
     e:'ต้องปรับรายการตัดบัญชีให้เสร็จก่อนแล้วจึงปันส่วนเสมอ เพราะกำไรขาดทุนที่นำมาแบ่งต้องเป็นตัวเลขในมุมของกลุ่มแล้ว · การหยิบตัวเลขดิบจากงบบริษัทย่อยมาคูณสัดส่วนเลยเป็นข้อผิดพลาดที่พบบ่อยที่สุดของโจทย์ประเภทนี้'},
    {ch:6, q:'ข้อใดคือความแตกต่างที่สำคัญที่สุดระหว่างการแสดงยอดติดลบของ NCI ในงบรวม กับการแสดงเงินลงทุนในบริษัทร่วมที่ติดลบ',
     o:['NCI แสดงเป็นจำนวนติดลบในส่วนของเจ้าของได้ แต่เงินลงทุนในบริษัทร่วมที่ติดลบต้องย้ายไปแสดงเป็นหนี้สิน','ทั้งสองอย่างแสดงเป็นจำนวนติดลบในสินทรัพย์ได้เหมือนกัน','ทั้งสองอย่างต้องปัดขึ้นเป็นศูนย์เหมือนกัน','NCI ต้องย้ายไปเป็นหนี้สิน ส่วนเงินลงทุนแสดงติดลบได้'], a:0,
     e:'NCI อยู่ในส่วนของเจ้าของซึ่งแสดงจำนวนติดลบได้ตามปกติ · แต่เงินลงทุนเป็นสินทรัพย์ซึ่งติดลบไม่ได้ เมื่อมีภาระผูกพันจนต้องรับรู้ขาดทุนเกินมูลค่าเงินลงทุน ส่วนที่เกินจึงต้องแสดงเป็นหนี้สิน'},
    {ch:7, q:'คำว่า ตัดรายการแบบเต็มจำนวน ใน TFRS 10 ย่อหน้า ข86.3 หมายความว่าอย่างไร',
     o:['ตัดรายการระหว่างกันออกทั้งร้อยเปอร์เซ็นต์ ไม่ว่าบริษัทใหญ่จะถือหุ้นกี่เปอร์เซ็นต์','ตัดตามสัดส่วนที่บริษัทใหญ่ถือหุ้นอยู่','ตัดเฉพาะรายการที่มีมูลค่าเกินเกณฑ์นัยสำคัญ','ตัดเฉพาะรายการที่เกิดขึ้นในงวดปัจจุบัน'], a:0,
     e:'เต็มจำนวนคือร้อยเปอร์เซ็นต์ของตัวรายการ ไม่เกี่ยวกับสัดส่วนการถือหุ้น · สัดส่วนการถือหุ้นมีผลแค่ตอนแบ่งภาระของกำไรที่ยังไม่เกิดว่าใครรับ ซึ่งเป็นคนละเรื่องกับจำนวนที่ตัด · ส่วนการตัดเฉพาะส่วนของผู้ลงทุนเป็นกฎของบริษัทร่วมตาม TAS 28 คนละมาตรฐานกัน'},
    {ch:7, q:'ประโยคใดสรุปหลักของทั้งบทรายการระหว่างบริษัทในเครือได้ตรงที่สุด',
     o:['กำไรจากการขายกันเองยังไม่ใช่กำไร จนกว่าของจะออกไปสู่คนนอกกลุ่ม','รายการระหว่างกันทุกรายการต้องถูกตัดทิ้งและไม่มีวันกลับมารับรู้','กำไรระหว่างกันรับรู้ได้ทันทีถ้าทั้งสองบริษัทบันทึกตรงกัน','กำไรระหว่างกันให้รับรู้ตามสัดส่วนการถือหุ้นเสมอ'], a:0,
     e:'ทั้งบทสรุปลงเหลือประโยคนี้ประโยคเดียว · กำไรไม่ได้หายไปไหน แต่ถูกเลื่อนไปโผล่ในปีที่ของออกไปนอกกลุ่มจริง ซึ่งเห็นได้ชัดจากการตรวจสองปีรวมว่ากำไรสะสมเท่ากับกำไรในมุมของกลุ่มพอดีเสมอ'},
    {ch:7, q:'การตัดรายการขายเชื่อระหว่างกันออกจากงบรวม ส่งผลต่อกำไรสุทธิของกลุ่มอย่างไร',
     o:['ไม่กระทบกำไรสุทธิเลย เพราะตัดออกทั้งฝั่งรายได้และฝั่งค่าใช้จ่ายเท่ากัน','ทำให้กำไรสุทธิลดลงเท่ากับยอดขายที่ถูกตัด','ทำให้กำไรสุทธิเพิ่มขึ้นเท่ากับกำไรขั้นต้นของรายการนั้น','ทำให้กำไรสุทธิลดลงตามสัดส่วนของ NCI'], a:0,
     e:'ตัดขายออกเท่าไรก็ตัดต้นทุนขายออกเท่านั้น กำไรจึงไม่ขยับ · สิ่งที่เปลี่ยนคือขนาดของยอดขายและของสินทรัพย์หนี้สินที่ไม่พองเกินจริง ซึ่งสำคัญกับอัตราส่วนทางการเงินและการประเมินขนาดกิจการ · ส่วนรายการที่กระทบกำไรคือรายการที่มีกำไรค้างอยู่ในสินทรัพย์ ซึ่งเป็นคนละประเภทกัน'},
    {ch:7, q:'ทำไมรายการตัดบัญชีในกระดาษทำการจึงต้องทำใหม่ทุกปี ทั้งที่ปีก่อนก็ตัดไปแล้ว',
     o:['เพราะรายการในกระดาษทำการไม่ใช่สมุดรายวัน ไม่เคยถูกบันทึกในสมุดของบริษัทใด งบของแต่ละบริษัทปีถัดไปจึงยังไม่ถูกตัดอะไรเลย','เพราะมาตรฐานกำหนดให้ทบทวนรายการตัดบัญชีทุกปี','เพราะตัวเลขเปลี่ยนไปตามอัตราเงินเฟ้อ','เพราะผู้สอบบัญชีกำหนดให้ทำใหม่ทุกปี'], a:0,
     e:'อาจารย์เขียนเตือนไว้ในสไลด์ว่า This Is Not Journal Entry · รายการตัดบัญชีมีชีวิตอยู่แค่ในกระดาษทำการแผ่นนั้น ไม่เคยเข้าสมุดของบริษัทใหญ่หรือบริษัทย่อย ปีถัดไปจึงเริ่มจากงบที่ยังไม่ถูกตัดอะไรเสมอ'},
    {ch:7, q:'บริษัทใหญ่ขายสินทรัพย์ราคาตามบัญชี 100 ให้บริษัทย่อยในราคา 130 และของยังอยู่ในกลุ่ม ถ้าไม่ปรับอะไรเลย งบรวมจะผิดอย่างไร',
     o:['ทั้งสินทรัพย์และกำไรสูงเกินจริง เพราะกลุ่มไม่ได้ขายอะไรให้ใครและของยังอยู่ที่เดิม','เฉพาะกำไรที่สูงเกินจริง ส่วนสินทรัพย์ถูกต้องแล้ว','เฉพาะสินทรัพย์ที่สูงเกินจริง ส่วนกำไรถูกต้องแล้ว','ไม่ผิดอะไร เพราะทั้งสองบริษัทบันทึกถูกต้องตามเอกสาร'], a:0,
     e:'ผิดทั้งสองอย่าง · สินทรัพย์จะแสดง 130 ทั้งที่ราคาทุนของกลุ่มยังเป็น 100 และกำไร 30 จะปรากฏทั้งที่กลุ่มยังไม่ได้ขายอะไรออกไปเลย · ทั้งสองบริษัทบันทึกถูกต้องในงบของตัวเองก็จริง แต่เมื่อมองเป็นหน่วยเดียวกันแล้วไม่ถูกต้อง'},
    {ch:7, q:'หลักว่า ใครขาย คนนั้นแบกกำไรที่ยังไม่เกิด มีความหมายอย่างไร',
     o:['บริษัทใหญ่ขายลงไป บริษัทใหญ่แบกเต็มจำนวน แต่บริษัทย่อยขายขึ้นมา ต้องแบ่งภาระกับ NCI ตามสัดส่วน','ใครขายคนนั้นได้กำไรไปเต็มจำนวนทันที','ใครขายคนนั้นต้องจ่ายภาษีแทนอีกฝ่าย','ใครขายคนนั้นต้องเป็นผู้จัดทำกระดาษทำการ'], a:0,
     e:'กำไรที่ยังไม่เกิดฝังอยู่ในงบของผู้ขาย · ถ้าอยู่ในงบบริษัทใหญ่ NCI ไม่ได้ถือหุ้นในบริษัทใหญ่จึงไม่ต้องรับภาระเลย แต่ถ้าอยู่ในงบบริษัทย่อย NCI ถือหุ้นอยู่ด้วยจึงต้องรับไปตามส่วน'},
    {ch:7, q:'ถ้าเปลี่ยนโจทย์จาก Downstream เป็น Upstream โดยตัวเลขอื่นเหมือนเดิมทุกตัว สิ่งใดจะไม่เปลี่ยน',
     o:['กำไรสุทธิรวมของกลุ่มและสินทรัพย์รวมของกลุ่ม','กำไรส่วนของบริษัทใหญ่','กำไรส่วนของ NCI','ยอดเงินลงทุนในบริษัทย่อยตามวิธีส่วนได้เสีย'], a:0,
     e:'ทิศทางของการขายไม่ได้เปลี่ยนว่ากลุ่มทำกำไรได้เท่าไรหรือมีสินทรัพย์เท่าไร เปลี่ยนแค่ว่ากำไรก้อนเดียวกันนั้นถูกแบ่งระหว่างบริษัทใหญ่กับ NCI อย่างไร · ตัวเลือกที่เหลือทั้งสามเปลี่ยนหมด และผลต่างจะออกมาเป็นสัดส่วนของ NCI คูณกำไรที่ค้างเสมอ'},
    {ch:7, q:'เหตุใดการตัดกำไรระหว่างกันกับบริษัทร่วมจึงให้คำตอบเท่ากันไม่ว่าจะเป็น Downstream หรือ Upstream',
     o:['เพราะบริษัทร่วมไม่ได้ถูกนำมารวมงบบรรทัดต่อบรรทัด จึงไม่มี NCI ให้ต้องแบ่งภาระด้วย','เพราะบริษัทร่วมไม่มีรายการระหว่างกันกับผู้ลงทุน','เพราะมาตรฐานกำหนดให้ตัดเต็มจำนวนทั้งสองทิศทาง','เพราะผู้ลงทุนในบริษัทร่วมถือหุ้นไม่เกินร้อยละห้าสิบเสมอ'], a:0,
     e:'ความต่างระหว่าง Downstream กับ Upstream ในกรณีบริษัทย่อย เกิดจากการที่ต้องแบ่งภาระกับ NCI · บริษัทร่วมแสดงเป็นเงินลงทุนก้อนเดียว ไม่มี NCI อยู่ในสมการ ผลจึงออกมาเท่ากันเสมอ และตัดเฉพาะส่วนของผู้ลงทุนตาม TAS 28 ย่อหน้า 28'},
    {ch:7, q:'ความต่างเชิงแนวคิดระหว่างกำไรระหว่างกันจากที่ดิน กับจากสินทรัพย์ที่มีค่าเสื่อมราคา คืออะไร',
     o:['ที่ดินค้างอยู่เฉย ๆ จนกว่าจะขายออกนอกกลุ่ม ส่วนสินทรัพย์ที่มีค่าเสื่อมทยอยรับรู้ทุกงวดที่คิดค่าเสื่อม','ที่ดินทยอยรับรู้ทุกปี ส่วนสินทรัพย์ที่มีค่าเสื่อมค้างอยู่จนกว่าจะขาย','ทั้งสองอย่างทยอยรับรู้เหมือนกัน','ทั้งสองอย่างไม่ต้องตัดกำไรระหว่างกันเลย'], a:0,
     e:'ที่ดินไม่มีค่าเสื่อมราคา จึงไม่มีกลไกใดมาทยอยรับรู้กำไรที่ค้างไว้ ต้องรอให้ขายออกนอกกลุ่ม · ส่วนสินทรัพย์ที่มีค่าเสื่อม ผู้ซื้อคิดค่าเสื่อมจากราคาที่สูงเกินจริง ส่วนเกินของค่าเสื่อมแต่ละปีจึงเท่ากับกำไรที่เกิดขึ้นจริงแล้วทีละงวด'},
    {ch:7, q:'ในปีที่สองหลังจากขายสินทรัพย์ที่มีค่าเสื่อมราคาระหว่างกัน บรรทัดกำไรจากการขายหายไปจากกระดาษทำการ แต่รายการใดยังต้องทำอยู่',
     o:['ยังต้องตัดราคาสินทรัพย์และค่าเสื่อมราคาสะสมที่สูงเกินจริงทุกปี จนกว่าจะตัดค่าเสื่อมหมดหรือขายออก','ไม่ต้องทำอะไรอีกแล้ว เพราะกำไรถูกตัดไปตั้งแต่ปีแรก','ต้องตั้งกำไรจากการขายขึ้นใหม่ทุกปี','ต้องปรับย้อนหลังงบปีแรก'], a:0,
     e:'กำไรถูกปิดเข้ากำไรสะสมไปแล้ว บรรทัดกำไรจึงหายไป แต่ตัวสินทรัพย์ในงบของผู้ซื้อยังบันทึกไว้สูงเกินจริงอยู่ และค่าเสื่อมสะสมก็ยังสูงเกินจริงตามไปด้วย จึงต้องตัดทุกปี · นี่คือเหตุผลเดียวกับที่รายการตัดบัญชีต้องทำใหม่ทุกปี'},
    {ch:7, q:'ทำไมการที่บริษัทย่อยซื้อหุ้นกู้ของบริษัทใหญ่โดยตรงในวันออกหุ้นกู้ จึงไม่เกิดกำไรขาดทุนจากการไถ่ถอน',
     o:['เพราะราคาที่จ่ายเท่ากับราคาตามบัญชีของหนี้ส่วนที่ถูกซื้อพอดี จึงไม่มีผลต่าง','เพราะมาตรฐานห้ามรับรู้กำไรจากการไถ่ถอนในปีแรก','เพราะหุ้นกู้ยังไม่ครบกำหนด','เพราะบริษัทย่อยไม่ใช่คู่สัญญาที่แท้จริง'], a:0,
     e:'ซื้อโดยตรงจากผู้ออกในวันเดียวกันด้วยเงื่อนไขเดียวกัน ราคาที่จ่ายจึงเท่ากับสัดส่วนของราคาตามบัญชีของหนี้พอดี · กำไรขาดทุนจะเกิดก็ต่อเมื่อซื้อจากตลาดภายนอกในราคาที่ต่างจากราคาตามบัญชีของหนี้ ซึ่งเป็นกรณีของการไถ่ถอนโดยอนุมาน'},
    {ch:7, q:'Constructive retirement หรือการไถ่ถอนโดยอนุมาน หมายถึงอะไร',
     o:['การที่บริษัทในเครือซื้อหุ้นกู้ของอีกบริษัทในกลุ่มจากคนนอก ซึ่งงบรวมถือเสมือนว่าหุ้นกู้ถูกไถ่ถอนไปแล้ว','การไถ่ถอนหุ้นกู้ก่อนครบกำหนดโดยจ่ายเงินให้ผู้ถือจริง','การแปลงหุ้นกู้เป็นหุ้นสามัญ','การที่ผู้ออกหุ้นกู้ผิดนัดชำระหนี้'], a:0,
     e:'หุ้นกู้ยังไม่ถูกไถ่ถอนจริงในทางกฎหมาย แต่เมื่อมองกลุ่มเป็นหน่วยเดียว การที่บริษัทหนึ่งในกลุ่มไปถือหนี้ของอีกบริษัทในกลุ่ม ก็เท่ากับกลุ่มซื้อหนี้ตัวเองคืน งบรวมจึงถือเสมือนว่าไถ่ถอนแล้วและรับรู้กำไรขาดทุนจากผลต่าง'},
    {ch:7, q:'ตาม Agency Theory กำไรจากการไถ่ถอนโดยอนุมานควรเป็นของใคร และเพราะเหตุใด',
     o:['เป็นของบริษัทผู้ออกหุ้นกู้ทั้งจำนวน เพราะผู้ซื้อทำหน้าที่เป็นเพียงตัวแทนในการไถ่ถอนแทน','เป็นของบริษัทผู้ซื้อหุ้นกู้ทั้งจำนวน เพราะเป็นผู้ลงเงินซื้อ','แบ่งครึ่งระหว่างผู้ออกกับผู้ซื้อเสมอ','แบ่งตามสัดส่วนการถือหุ้นระหว่างบริษัทใหญ่กับ NCI เสมอ'], a:0,
     e:'ผู้ซื้อหุ้นกู้ถูกมองว่าทำหน้าที่เป็นตัวแทนของผู้ออกในการไถ่ถอนหนี้ของผู้ออก กำไรขาดทุนจึงเป็นของผู้ออกทั้งจำนวน · ข้อนี้มีผลจริงในการปันส่วน ถ้าผู้ออกคือบริษัทใหญ่ก็ไม่ต้องแบ่งให้ NCI เลย แต่ถ้าผู้ออกเป็นบริษัทย่อยจึงจะต้องแบ่ง'},
    {ch:7, q:'กำไรจากการไถ่ถอนโดยอนุมานที่รับรู้ในปีแรก ในปีถัด ๆ ไปจะเกิดอะไรขึ้น และเพราะอะไร',
     o:['ทยอยกลับออกจนหมดพอดีเมื่อหุ้นกู้ครบกำหนด เพราะกำไรนั้นคือการบอกล่วงหน้าว่ากลุ่มจะจ่ายดอกเบี้ยน้อยกว่าที่บันทึกไว้','คงอยู่ตลอดไป ไม่ต้องปรับอะไรอีก','เพิ่มขึ้นทุกปีตามอัตราดอกเบี้ยที่แท้จริง','ต้องกลับรายการทั้งหมดในปีที่สองทันที'], a:0,
     e:'กำไรก้อนนั้นไม่ใช่เงินที่ได้มาฟรี แต่เป็นการรับรู้ล่วงหน้าว่าภาระดอกเบี้ยในอนาคตจะน้อยกว่าที่บันทึกไว้ · ความจริงข้อนั้นจึงทยอยกลับออกมาในแต่ละปีที่เหลือ และต้องหมดพอดีเมื่อหุ้นกู้ครบกำหนด ซึ่งเป็นจุดตรวจงานที่ดีที่สุดของเรื่องนี้'},
    {ch:7, q:'ประโยคท้ายของ TFRS 10 ย่อหน้า ข86.3 ที่ว่าขาดทุนในรายการระหว่างกันอาจบ่งชี้ถึงการด้อยค่า มีนัยอย่างไร',
     o:['ขาดทุนระหว่างกันตัดเหมือนกำไร แต่ถ้าสะท้อนการด้อยค่าจริงให้เก็บไว้เป็นขาดทุนของกลุ่ม','ขาดทุนระหว่างกันทุกกรณีต้องรับรู้เต็มจำนวนทันที','ขาดทุนระหว่างกันห้ามตัดออกไม่ว่ากรณีใด','ขาดทุนระหว่างกันให้บันทึกเป็นค่าความนิยมติดลบ'], a:0,
     e:'โดยหลักขาดทุนระหว่างกันก็เป็นขาดทุนปลอมเหมือนกำไรปลอม ต้องตัดออก · แต่ถ้าของนั้นเสียมูลค่าจริง เช่น เข้าเกณฑ์ราคาทุนหรือมูลค่าสุทธิที่จะได้รับแล้วแต่ราคาใดต่ำกว่า ขาดทุนส่วนนั้นเป็นขาดทุนจริงของกลุ่ม ต้องเก็บไว้'},
    {ch:8, q:'เหตุใดมูลค่าที่คาดว่าจะได้รับคืนจึงเลือกจำนวนที่สูงกว่าของสองฐาน ไม่ใช่ต่ำกว่า',
     o:['เพราะกิจการที่มีเหตุผลย่อมเลือกทางที่ได้เงินกลับมามากที่สุด ขายได้มากกว่าก็ขาย ใช้ต่อได้มากกว่าก็ใช้ต่อ','เพราะหลักความระมัดระวังกำหนดให้เลือกจำนวนที่สูงกว่า','เพราะมูลค่าจากการใช้สูงกว่ามูลค่ายุติธรรมเสมอ','เพราะต้องการให้สินทรัพย์ไม่ด้อยค่าบ่อยเกินไป'], a:0,
     e:'สินทรัพย์มีทางได้เงินคืนสองทาง คือขายหรือใช้ต่อ กิจการย่อมเลือกทางที่ดีกว่า การด้อยค่าจึงเกิดก็ต่อเมื่อแม้แต่ทางที่ดีที่สุดก็ยังได้คืนไม่ถึงมูลค่าตามบัญชี · ข้อสอบชอบสลับเป็นตัวที่ต่ำกว่า ซึ่งเป็นการสับสนกับเกณฑ์ราคาทุนหรือมูลค่าสุทธิที่จะได้รับของสินค้าคงเหลือ'},
    {ch:8, q:'ทำไมค่าความนิยมจึงทดสอบการด้อยค่าแบบเดี่ยว ๆ ไม่ได้',
     o:['เพราะค่าความนิยมไม่ก่อให้เกิดกระแสเงินสดด้วยตัวเอง จึงต้องยกไปทดสอบรวมกับหน่วยสินทรัพย์','เพราะค่าความนิยมไม่มีราคาตลาดอ้างอิง','เพราะค่าความนิยมไม่ได้บันทึกแยกเป็นบัญชีต่างหาก','เพราะมาตรฐานห้ามทดสอบค่าความนิยมเกินปีละครั้ง'], a:0,
     e:'มูลค่าที่คาดว่าจะได้รับคืนต้องคำนวณจากกระแสเงินสด แต่ค่าความนิยมเป็นผลต่างที่เหลือจากการซื้อกิจการ ไม่มีกระแสเงินสดของตัวเอง จึงต้องปันส่วนเข้าไปอยู่ในหน่วยสินทรัพย์แล้วทดสอบทั้งหน่วย · ความจำเป็นข้อนี้คือต้นเหตุของความซับซ้อนทั้งหมดในบทนี้'},
    {ch:8, q:'ทำไมมาตรฐานจึงกำหนดว่าหน่วยที่รับปันส่วนค่าความนิยมต้องไม่ใหญ่เกินส่วนงานดำเนินงาน',
     o:['เพราะถ้าหน่วยใหญ่เกินไป กำไรของธุรกิจที่ดีจะกลบการด้อยค่าของธุรกิจที่แย่จนไม่มีวันเห็นผลขาดทุน','เพราะหน่วยใหญ่เกินไปจะคำนวณกระแสเงินสดไม่ได้','เพราะส่วนงานดำเนินงานเป็นหน่วยที่เล็กที่สุดที่กฎหมายยอมรับ','เพราะหน่วยใหญ่เกินไปจะทำให้ค่าความนิยมสูงเกินจริง'], a:0,
     e:'นี่คือกลไกกันการซ่อนการด้อยค่า · ถ้าปล่อยให้เอาค่าความนิยมไปกองรวมที่ระดับบริษัททั้งบริษัท ธุรกิจที่เจ๊งไปแล้วหนึ่งหน่วยจะถูกกำไรของอีกเก้าหน่วยกลบจนไม่มีวันด้อยค่า · ขอบล่างคือเล็กที่สุดเท่าที่ฝ่ายบริหารใช้ติดตามจริง ขอบบนคือไม่เกินส่วนงานดำเนินงาน'},
    {ch:8, q:'เหตุใดจึงต้องทดสอบการด้อยค่าของสินทรัพย์รายตัวก่อนทดสอบหน่วยสินทรัพย์ที่มีค่าความนิยม',
     o:['เพื่อไม่ให้ค่าความนิยมต้องรับภาระการด้อยค่าแทนสินทรัพย์ที่ด้อยค่าด้วยตัวเองอยู่แล้ว','เพราะสินทรัพย์รายตัวมีมูลค่าสูงกว่าค่าความนิยมเสมอ','เพราะมาตรฐานกำหนดให้ทดสอบเรียงตามอายุการใช้งาน','เพราะค่าความนิยมทดสอบได้ปีละครั้งเท่านั้น'], a:0,
     e:'ถ้าไม่ตัดสินทรัพย์ที่ด้อยค่าอยู่แล้วลงก่อน พอเอาไปรวมเป็นหน่วย มูลค่าตามบัญชีของหน่วยจะสูงเกินจริง และค่าความนิยมซึ่งรับผลขาดทุนเป็นลำดับแรกจะต้องรับภาระแทน ทั้งที่ไม่ใช่เรื่องของมัน'},
    {ch:8, q:'เหตุใดหน่วยสินทรัพย์ที่มีค่าความนิยมจึงต้องทดสอบทุกปี ขณะที่สินทรัพย์ทั่วไปทดสอบเมื่อมีข้อบ่งชี้เท่านั้น',
     o:['เพราะค่าความนิยมไม่ถูกตัดจำหน่าย ถ้าไม่บังคับทดสอบทุกปีก็จะค้างอยู่ในงบตลอดไปโดยไม่มีใครตรวจ','เพราะค่าความนิยมมีมูลค่าสูงกว่าสินทรัพย์อื่นเสมอ','เพราะค่าความนิยมเปลี่ยนแปลงเร็วกว่าสินทรัพย์อื่น','เพราะผู้สอบบัญชีต้องการหลักฐานเพิ่มเติม'], a:0,
     e:'สินทรัพย์ที่ตัดค่าเสื่อมหรือตัดจำหน่าย มูลค่าตามบัญชีจะลดลงเองตามอายุ แต่ค่าความนิยมอยู่นิ่งตลอดกาล · การบังคับทดสอบทุกปีจึงเป็นกลไกเดียวที่ทำให้ค่าความนิยมถูกสอบทานอย่างสม่ำเสมอ'},
    {ch:8, q:'เหตุใดค่าความนิยมจึงต้องรับผลขาดทุนจากการด้อยค่าก่อนสินทรัพย์อื่นในหน่วยเดียวกัน',
     o:['เพราะเป็นรายการที่วัดมูลค่าได้ยากที่สุดและสะท้อนความคาดหวังที่อาจไม่เป็นจริงมากที่สุด','เพราะค่าความนิยมมีมูลค่าน้อยที่สุดในหน่วย','เพราะค่าความนิยมไม่มีผลต่อภาษีเงินได้','เพราะสินทรัพย์อื่นมีมูลค่ายุติธรรมอ้างอิงได้เสมอ'], a:0,
     e:'ค่าความนิยมคือส่วนที่จ่ายเกินไปเพราะคาดหวังประโยชน์ในอนาคต เมื่อหน่วยนั้นทำเงินได้ไม่ถึงที่คาด สิ่งแรกที่ควรหายไปคือความคาดหวังนั้น ไม่ใช่สินทรัพย์ที่จับต้องได้ซึ่งยังมีมูลค่าของตัวเอง'},
    {ch:8, q:'เมื่อ NCI วัดด้วยวิธีสัดส่วนของสินทรัพย์สุทธิ ปัญหาเชิงแนวคิดในการทดสอบการด้อยค่าคืออะไร',
     o:['ฝั่งมูลค่าที่ได้รับคืนเป็นของทั้งหน่วยร้อยเปอร์เซ็นต์ แต่ฝั่งมูลค่าตามบัญชีมีค่าความนิยมเฉพาะส่วนของบริษัทใหญ่ จึงเทียบกันตรง ๆ ไม่ได้','ค่าความนิยมของ NCI ถูกบันทึกซ้ำสองครั้ง','มูลค่าที่ได้รับคืนคำนวณได้เฉพาะส่วนของบริษัทใหญ่','NCI ไม่มีสิทธิในกระแสเงินสดของหน่วยสินทรัพย์'], a:0,
     e:'เป็นการเทียบของสองอย่างที่วัดด้วยไม้บรรทัดคนละอัน · กระแสเงินสดที่หน่วยทำได้ไม่ได้แบ่งว่าส่วนไหนของใคร แต่ค่าความนิยมในงบมีเฉพาะส่วนของบริษัทใหญ่ ทำให้ฝั่งมูลค่าตามบัญชีดูเล็กกว่าความจริงและตรวจไม่พบการด้อยค่า'},
    {ch:8, q:'เมื่อ gross up ค่าความนิยมแล้วทดสอบจนได้ผลขาดทุน จะรับรู้ในงบการเงินรวมเท่าใด',
     o:['เฉพาะส่วนที่ปันไปยังบริษัทใหญ่ เพราะส่วนของ NCI ไม่เคยอยู่ในงบมาตั้งแต่ต้น','เต็มจำนวนที่คำนวณได้ เพราะทดสอบจากฐานเต็มแล้ว','เฉพาะส่วนของ NCI เท่านั้น','ครึ่งหนึ่งของจำนวนที่คำนวณได้'], a:0,
     e:'หลักสั้น ๆ คือ บวกกลับตอนทดสอบ แต่ไม่บวกกลับตอนลงบัญชี · ค่าความนิยมของ NCI ที่บวกกลับเข้าไปเป็นตัวเลขสมมติที่ใส่เพื่อให้เทียบกันได้อย่างยุติธรรมเท่านั้น ไม่เคยอยู่ในงบจริง จึงรับรู้การด้อยค่าของมันไม่ได้'},
    {ch:8, q:'เหตุใดกรณี NCI วัดด้วยมูลค่ายุติธรรม จึงรับรู้ผลขาดทุนจากการด้อยค่าเต็มจำนวน ต่างจากกรณีวิธีสัดส่วน',
     o:['เพราะค่าความนิยมของ NCI อยู่ในงบการเงินรวมอยู่แล้วตั้งแต่วันซื้อ จึงไม่ต้องบวกกลับและตัดได้เต็ม','เพราะวิธีมูลค่ายุติธรรมให้ค่าความนิยมสูงกว่าเสมอ','เพราะมาตรฐานกำหนดให้ใช้วิธีนี้เป็นหลัก','เพราะ NCI ที่วัดด้วยมูลค่ายุติธรรมถือเป็นหนี้สิน'], a:0,
     e:'ความต่างทั้งหมดมาจากว่าค่าความนิยมของ NCI อยู่ในงบหรือไม่ · วิธีมูลค่ายุติธรรมบันทึกค่าความนิยมทั้งก้อนไว้ตั้งแต่ต้น จึงตัดได้เต็มแล้วค่อยแบ่งภาระ ส่วนวิธีสัดส่วนบันทึกเฉพาะส่วนของบริษัทใหญ่ จึงตัดได้เพียงส่วนนั้น'},
    {ch:8, q:'เมื่อผลขาดทุนที่ปันให้ NCI มากกว่าค่าความนิยมส่วนของ NCI ที่มีอยู่ ต้องทำอย่างไร',
     o:['ตรึง NCI ไว้ที่ศูนย์ แล้วผลักส่วนเกินไปให้บริษัทใหญ่รับแทน','ปล่อยให้ค่าความนิยมส่วนของ NCI ติดลบตามจริง','ยกเลิกการรับรู้ผลขาดทุนทั้งจำนวน','โอนส่วนเกินไปลดสินทรัพย์หมุนเวียนแทน'], a:0,
     e:'ชนเพดานที่ห้ามลดสินทรัพย์ต่ำกว่าศูนย์ จึงตรึงไว้ที่ศูนย์แล้วผลักส่วนเกินให้บริษัทใหญ่ · ผลคือในงบกำไรขาดทุน NCI รับผลขาดทุนน้อยกว่าสัดส่วนที่ควรจะเป็น และในงบฐานะการเงินค่าความนิยมส่วนของ NCI เหลือศูนย์ ไม่ใช่ติดลบ'},
    {ch:8, q:'เหตุใดมาตรฐานจึงห้ามกลับรายการขาดทุนจากการด้อยค่าของค่าความนิยมโดยเด็ดขาด',
     o:['เพราะค่าความนิยมที่ฟื้นขึ้นมาถือเป็นค่าความนิยมที่กิจการสร้างขึ้นเอง ซึ่งห้ามรับรู้อยู่แล้ว','เพราะการกลับรายการจะทำให้กำไรสูงเกินจริง','เพราะค่าความนิยมไม่มีมูลค่ายุติธรรมให้อ้างอิง','เพราะค่าความนิยมถูกตัดจำหน่ายไปแล้ว'], a:0,
     e:'ถ้ายอมให้กลับรายการ ก็เท่ากับเปิดประตูหลังให้บันทึกค่าความนิยมที่สร้างขึ้นเองเข้างบได้ ซึ่งมาตรฐานห้ามมาตั้งแต่ต้น · สินทรัพย์อื่นกลับรายการได้เพราะพิสูจน์ได้ว่าเป็นตัวเดิมที่มูลค่าฟื้นกลับมา แต่ค่าความนิยมแยกไม่ออกว่าก้อนไหนเป็นของเดิม'},
    {ch:8, q:'เมื่อขายการดำเนินงานที่อยู่ภายใต้หน่วยสินทรัพย์ออกไปบางส่วน ค่าความนิยมต้องปฏิบัติอย่างไร',
     o:['ยกค่าความนิยมติดไปกับส่วนที่ขายตามเกณฑ์มูลค่าเปรียบเทียบ เพื่อคำนวณกำไรขาดทุนจากการจำหน่าย','เก็บค่าความนิยมไว้ทั้งหมดกับส่วนที่ยังคงอยู่','ตัดค่าความนิยมทั้งก้อนเป็นค่าใช้จ่ายทันที','ไม่ต้องทำอะไร เพราะค่าความนิยมไม่เกี่ยวกับการขาย'], a:0,
     e:'ถ้าไม่ยกค่าความนิยมติดไปด้วย กำไรจากการขายจะสูงเกินจริงเพราะต้นทุนของสิ่งที่ขายไม่ครบ และค่าความนิยมที่ค้างอยู่ก็จะไม่มีธุรกิจรองรับ ซึ่งจะไปโผล่เป็นการด้อยค่าในปีถัดไปแทน'},
    {ch:9, q:'คำใดเป็นตัวชี้ขาดว่าการงานหนึ่งเป็นการร่วมการงานตาม TFRS 11 หรือไม่',
     o:['ความเห็นชอบอย่างเป็นเอกฉันท์ในการตัดสินใจเกี่ยวกับกิจกรรมที่เกี่ยวข้อง','สัดส่วนการถือหุ้นที่เท่ากันทุกฝ่าย','จำนวนผู้เข้าร่วมตั้งแต่สามรายขึ้นไป','การจัดตั้งเป็นบริษัทจำกัด'], a:0,
     e:'เอกฉันท์คือคำชี้ขาด · ถ้าฝ่ายใดตัดสินใจเองได้คือการควบคุม เข้า TFRS 10 เป็นบริษัทย่อย ถ้าต้องเห็นชอบร่วมกันทุกฝ่ายคือการควบคุมร่วม เข้า TFRS 11 · สัดส่วนที่เท่ากันหรือการไม่มีใครถือเกินครึ่งไม่ได้แปลว่ามีการควบคุมร่วม เช่นในกรณี กฟน. ที่ถือร้อยละสามสิบ ขณะที่อีกสองรายถือร้อยละสามสิบห้าเท่ากัน'},
    {ch:9, q:'คำใดเป็นเส้นแบ่งระหว่างการดำเนินงานร่วมกันกับการร่วมค้า',
     o:['คำว่าสุทธิ · มีสิทธิในสินทรัพย์สุทธิคือการร่วมค้า ส่วนมีสิทธิในสินทรัพย์และภาระในหนี้สินโดยตรงคือการดำเนินงานร่วมกัน','จำนวนผู้เข้าร่วมการงาน','ระยะเวลาของสัญญา','มูลค่าเงินลงทุนที่แต่ละฝ่ายใส่เข้าไป'], a:0,
     e:'สิทธิในสินทรัพย์และภาระในหนี้สินแปลว่าแตะตัวสินทรัพย์หนี้สินได้โดยตรง จึงนำมารวมในงบของตนตามส่วน · สิทธิในสินทรัพย์สุทธิแปลว่าแตะได้แค่ส่วนที่เหลือหลังหักหนี้ จึงบันทึกเป็นเงินลงทุนก้อนเดียวแล้วใช้วิธีส่วนได้เสีย'},
    {ch:9, q:'เหตุใดชื่อเต็มของ TAS 28 จึงบอกคำตอบของบทกิจการร่วมค้าไว้แล้ว',
     o:['เพราะชื่อคือ เงินลงทุนในบริษัทร่วมและการร่วมค้า ซึ่งแปลว่าการร่วมค้าใช้วิธีเดียวกับบริษัทร่วม','เพราะชื่อระบุว่าต้องใช้วิธีราคาทุน','เพราะชื่อระบุว่าต้องจัดทำงบการเงินรวม','เพราะชื่อระบุว่าต้องใช้วิธีรวมตามสัดส่วน'], a:0,
     e:'การที่มาตรฐานฉบับเดียวครอบคลุมทั้งบริษัทร่วมและการร่วมค้า บอกว่าทั้งสองใช้วิธีส่วนได้เสียเหมือนกัน ไม่มีวิธีพิเศษของการร่วมค้าเอง · วิธีรวมตามสัดส่วนถูกยกเลิกไปตั้งแต่ TFRS 11 แล้ว'},
    {ch:9, q:'ในงบของ กฟน. คอลัมน์วิธีส่วนได้เสียเคลื่อนไหวจาก 798 เป็น 788 ขณะที่งบเฉพาะกิจการนิ่งที่ 501 ข้อสรุปเชิงแนวคิดคืออะไร',
     o:['วิธีส่วนได้เสียสะท้อนผลการดำเนินงานของผู้ถูกลงทุน ส่วนวิธีราคาทุนสะท้อนเพียงเงินที่จ่ายไปครั้งแรก','วิธีราคาทุนให้ข้อมูลที่ถูกต้องกว่าเพราะไม่ผันผวน','ผลต่างเกิดจากอัตราแลกเปลี่ยน','ผลต่างเกิดจากการด้อยค่าของเงินลงทุน'], a:0,
     e:'ราคาทุนไม่เคยเปลี่ยนไม่ว่ากิจการร่วมค้าจะกำไรหรือขาดทุน เงินปันผลไปโผล่เป็นรายได้แทน · ส่วนวิธีส่วนได้เสียบวกส่วนแบ่งกำไรและหักเงินปันผลออกจากเงินลงทุน ยอดจึงขยับตามผลการดำเนินงานจริง · ผลต่าง 287 คือกำไรสะสมหลังวันลงทุนที่ยังไม่ได้จ่ายคืนออกมา ซึ่งวิธีราคาทุนมองไม่เห็น'},
    {ch:9, q:'เหตุใดเงินลงทุนในการร่วมค้าตามวิธีส่วนได้เสียจึงลดลงได้ ทั้งที่กิจการร่วมค้ามีกำไร',
     o:['เพราะเงินปันผลรับมากกว่าส่วนแบ่งกำไร และเงินปันผลถือเป็นการถอนทุนคืนจึงนำไปหักจากเงินลงทุน','เพราะต้องรับรู้การด้อยค่าของเงินลงทุนทุกปี','เพราะกำไรของกิจการร่วมค้าไม่นับในวิธีส่วนได้เสีย','เพราะต้องตัดจำหน่ายค่าความนิยมปีละงวด'], a:0,
     e:'ในวิธีส่วนได้เสียเงินปันผลไม่ใช่รายได้ แต่เป็นการที่ผู้ถูกลงทุนจ่ายทุนคืนให้ผู้ลงทุน จึงนำไปหักจากมูลค่าเงินลงทุน · เมื่อจ่ายคืนมากกว่าที่ทำกำไรได้ในปีนั้น ยอดเงินลงทุนจึงลดลง ซึ่งเป็นเรื่องปกติและไม่ได้แปลว่าขาดทุน'},
    {ch:9, q:'เหตุใดคอลัมน์ของ กฟน. จึงใช้ชื่อว่างบการเงินที่แสดงเงินลงทุนตามวิธีส่วนได้เสีย ไม่ใช่งบการเงินรวม',
     o:['เพราะการร่วมค้าไม่ถูกนำมารวมบรรทัดต่อบรรทัดเหมือนบริษัทย่อย แต่แสดงเป็นเงินลงทุนก้อนเดียว','เพราะ กฟน. ไม่มีบริษัทย่อยเลย','เพราะงบรวมต้องจัดทำโดยผู้สอบบัญชีเท่านั้น','เพราะการร่วมค้าถือเป็นกิจการต่างประเทศ'], a:0,
     e:'นี่คือความต่างที่สำคัญระหว่าง TFRS 10 กับ TFRS 11 · บริษัทย่อยถูกรวมบรรทัดต่อบรรทัดเพราะควบคุมได้ แต่การร่วมค้ามีเพียงสิทธิในสินทรัพย์สุทธิ จึงแสดงเป็นเงินลงทุนก้อนเดียว ชื่อของงบจึงต่างกันด้วย'},
    {ch:10, q:'TAS 24 ต่างจากมาตรฐานอื่นที่เรียนมาในวิชานี้อย่างไร',
     o:['เป็นมาตรฐานการเปิดเผยข้อมูล ไม่ใช่การรับรู้รายการ รายการกับคนในเครือลงบัญชีเหมือนรายการกับคนนอกทุกประการ','กำหนดให้บันทึกรายการกับคนในเครือด้วยราคาตลาดเสมอ','ห้ามทำรายการกับบุคคลที่เกี่ยวข้องกัน','กำหนดให้ตัดรายการกับบุคคลที่เกี่ยวข้องกันออกจากงบ'], a:0,
     e:'ทั้งบทไม่มีสมุดรายวันและไม่มีกระดาษทำการเลย เพราะมาตรฐานไม่ได้เปลี่ยนวิธีลงบัญชี แต่บังคับให้บอกผู้อ่านงบว่าทำกับใคร เท่าไร และด้วยเงื่อนไขอย่างไร · การตัดรายการระหว่างกันออกเป็นเรื่องของ TFRS 10 คนละมาตรฐาน'},
    {ch:10, q:'วลี โดยไม่คำนึงว่าได้มีการคิดราคาระหว่างกันหรือไม่ ในนิยามรายการระหว่างกัน มีนัยอย่างไร',
     o:['ให้เปล่าก็ต้องเปิดเผย เช่น ให้ใช้สำนักงานฟรีหรือค้ำประกันโดยไม่คิดค่าธรรมเนียม','ต้องเปิดเผยเฉพาะรายการที่มีการคิดราคา','ต้องเปิดเผยเฉพาะรายการที่คิดราคาต่ำกว่าตลาด','ต้องเปิดเผยเฉพาะรายการที่มีเอกสารใบกำกับภาษี'], a:0,
     e:'เป็นวลีที่ออกสอบบ่อยที่สุดของบท · รายการที่ไม่มีตัวเลขเข้าบัญชีเลยสักบาทก็ยังเป็นรายการระหว่างกันที่ต้องเปิดเผย · และจริง ๆ การให้เปล่านั่นแหละน่าสงสัยที่สุด เพราะไม่มีใครให้เปล่ากับคนนอก'},
    {ch:10, q:'เหตุใดกิจการสองแห่งที่มีกรรมการคนเดียวกันนั่งอยู่ทั้งสองแห่ง จึงยังไม่เป็นบุคคลที่เกี่ยวข้องกัน',
     o:['เพราะกรรมการคนเดียวไม่ได้แปลว่ามีอำนาจควบคุมหรืออิทธิพลอย่างมีนัยสำคัญเหนือกิจการนั้น','เพราะกรรมการไม่ใช่ผู้บริหารสำคัญ','เพราะมาตรฐานสนใจเฉพาะความสัมพันธ์ระหว่างนิติบุคคล','เพราะกรรมการไม่มีสิทธิออกเสียงในที่ประชุมผู้ถือหุ้น'], a:0,
     e:'มาตรฐานระบุไว้ชัดว่าการมีกรรมการหรือผู้บริหารสำคัญคนใดคนหนึ่งร่วมกันยังไม่พอ · แต่ต้องอ่านโจทย์ให้ครบ เพราะถ้าคนนั้นเป็นผู้บริหารสำคัญของทั้งสองแห่ง ก็อาจกลับเข้าเงื่อนไขข้ออื่นได้ · และกรรมการนับเป็นผู้บริหารสำคัญเสมอ ไม่ว่าจะบริหารงานประจำหรือไม่'},
    {ch:10, q:'ธนาคารที่ปล่อยกู้ก้อนใหญ่ให้บริษัทจนบริษัทพึ่งพาอย่างมาก เป็นบุคคลที่เกี่ยวข้องกันหรือไม่ เพราะเหตุใด',
     o:['ไม่เป็น เพราะการพึ่งพาทางเศรษฐกิจอย่างเดียวไม่ทำให้เป็น ต้องมีอำนาจควบคุมหรืออิทธิพลอย่างมีนัยสำคัญจริง','เป็น เพราะบริษัทพึ่งพาเงินกู้ก้อนนั้นอย่างมาก','เป็น เพราะธนาคารมีสิทธิเรียกหลักประกัน','ไม่เป็น เพราะธนาคารเป็นสถาบันการเงินที่กฎหมายยกเว้นไว้'], a:0,
     e:'มาตรฐานระบุผู้ให้การสนับสนุนทางการเงินไว้ในกลุ่มที่ไม่ใช่ RP โดยมีเงื่อนไขว่าไม่มีการควบคุม ควบคุมร่วม หรืออิทธิพลอย่างมีนัยสำคัญ · เกณฑ์คืออำนาจ ไม่ใช่ขนาดของการพึ่งพา · หลักเดียวกันใช้กับลูกค้ารายใหญ่และผู้ขายรายใหญ่ด้วย'},
    {ch:10, q:'การเปิดเผยข้อใดต้องทำเสมอ แม้ทั้งปีไม่มีรายการระหว่างกันแม้แต่บาทเดียว',
     o:['ความสัมพันธ์ระหว่างบริษัทใหญ่กับบริษัทย่อย พร้อมชื่อบริษัทใหญ่และผู้ควบคุมสูงสุด','จำนวนเงินของยอดคงค้างกับบุคคลที่เกี่ยวข้องกัน','ค่าเผื่อหนี้สงสัยจะสูญของลูกหนี้ที่เกี่ยวข้องกัน','ลักษณะของสิ่งตอบแทนที่ใช้ในการชำระหนี้'], a:0,
     e:'การเปิดเผยอื่นทั้งหมดขึ้นกับว่ามีรายการเกิดขึ้นหรือไม่ แต่ความสัมพันธ์บริษัทใหญ่กับบริษัทย่อยต้องเปิดเผยเสมอ · เพราะลำพังการมีอยู่ของความสัมพันธ์ก็เป็นข้อมูลแล้ว มันบอกผู้อ่านงบว่ามีคนที่สั่งการบริษัทนี้ได้อยู่'},
    {ch:10, q:'เหตุใด TAS 24 จึงบังคับให้เปิดเผยค่าเผื่อหนี้สงสัยจะสูญและหนี้สูญที่เกิดจากบุคคลที่เกี่ยวข้องกันด้วย',
     o:['เพราะการปล่อยสินเชื่อให้พวกเดียวกันแล้วเก็บเงินไม่ได้ เป็นช่องทางถ่ายเทความมั่งคั่งออกจากบริษัท','เพราะลูกหนี้ที่เกี่ยวข้องกันมีความเสี่ยงสูงกว่าลูกหนี้ทั่วไปเสมอ','เพราะมาตรฐานต้องการให้ตัดจำหน่ายลูกหนี้เหล่านี้ทันที','เพราะกฎหมายภาษีกำหนดไว้'], a:0,
     e:'การตั้งยอดขายให้พวกเดียวกันแล้วตั้งค่าเผื่อทิ้งทีหลัง เป็นวิธีถ่ายเทความมั่งคั่งที่คลาสสิกที่สุด · มาตรฐานจึงไม่ให้บอกแค่ยอดรายการ แต่ต้องบอกด้วยว่าเก็บเงินได้จริงหรือไม่'},
    {ch:10, q:'ในตารางรายการกับบุคคลที่เกี่ยวข้องกันของบริษัทจดทะเบียน เหตุใดแถวบริษัทย่อยในคอลัมน์งบการเงินรวมจึงมักเป็นขีด',
     o:['เพราะรายการกับบริษัทย่อยถูกตัดออกไปแล้วในงบรวม แต่ยังคงอยู่ในงบการเงินเฉพาะกิจการ','เพราะบริษัทย่อยไม่ใช่บุคคลที่เกี่ยวข้องกัน','เพราะรายการกับบริษัทย่อยไม่มีนัยสำคัญ','เพราะบริษัทย่อยไม่ได้จัดทำงบการเงิน'], a:0,
     e:'เป็นจุดที่เชื่อมบทนี้กลับไปหาเรื่องรายการระหว่างบริษัทในเครือโดยตรง · งบรวมมองกลุ่มเป็นหน่วยเดียว รายการระหว่างกันจึงถูกตัดหมด แต่งบเฉพาะกิจการมองบริษัทแม่เป็นหน่วยเดียว บริษัทย่อยยังเป็นคนนอก รายการจึงยังอยู่'},
    {ch:10, q:'เหตุใดมาตรฐานจึงให้ข้อยกเว้นแก่กิจการที่เกี่ยวข้องกับรัฐบาล และยกเว้นเรื่องใดบ้าง',
     o:['เพราะถ้าบังคับเต็มที่ รัฐวิสาหกิจจะต้องไล่รายการกับหน่วยงานรัฐทุกแห่ง ซึ่งทำไม่ไหว แต่ยังต้องเปิดเผยชื่อรัฐบาล ลักษณะความสัมพันธ์ และรายการที่มีนัยสำคัญ','เพราะรายการกับรัฐไม่มีความเสี่ยงต่อผู้ใช้งบการเงิน จึงยกเว้นทั้งหมด','เพราะรัฐบาลไม่ถือเป็นบุคคลที่เกี่ยวข้องกัน','เพราะข้อมูลของรัฐเป็นความลับทางราชการ'], a:0,
     e:'เหตุผลเป็นเรื่องความเป็นไปได้ในทางปฏิบัติล้วน ๆ ไม่ใช่ว่ารายการนั้นไม่สำคัญ · จึงยกเว้นเฉพาะการไล่รายละเอียดรายการทุกรายการ แต่ไม่ยกเว้นการบอกว่าเกี่ยวข้องกับใคร และไม่ยกเว้นรายการที่มีนัยสำคัญ'},
    {ch:10, q:'เหตุใดหมายเหตุประกอบงบจึงต้องบรรยายสัญญากับบุคคลที่เกี่ยวข้องกันเป็นความเรียง ไม่ใช่แสดงแต่ตัวเลขในตาราง',
     o:['เพราะต้องเปิดเผยข้อกำหนด เงื่อนไข หลักประกัน และลักษณะของสิ่งตอบแทนที่ใช้ชำระ ซึ่งใส่ในตารางตัวเลขไม่ได้','เพราะมาตรฐานห้ามแสดงรายการกับบุคคลที่เกี่ยวข้องกันเป็นตาราง','เพราะตัวเลขของรายการเหล่านี้เป็นความลับ','เพราะผู้สอบบัญชีต้องการคำอธิบายเพิ่มเติม'], a:0,
     e:'ตัวเลขบอกได้แค่ว่าทำไปเท่าไร แต่บอกไม่ได้ว่าเงื่อนไขดีหรือแย่กว่าที่ทำกับคนนอกอย่างไร · เงื่อนไขการเลิกสัญญา อัตราค่าธรรมเนียม และหลักประกัน คือสิ่งที่บอกว่ารายการนั้นสมเหตุสมผลหรือไม่'},
    {ch:10, q:'ข้อใดจัดเป็นบุคคลหรือกิจการที่เกี่ยวข้องกันกับกิจการที่เสนอรายงาน',
     o:['กิจการสองแห่งที่เป็นการร่วมค้าของบุคคลที่สามคนเดียวกัน','ลูกค้ารายใหญ่ที่ซื้อสินค้าเกินครึ่งของยอดขาย','ผู้จัดจำหน่ายที่เป็นตัวแทนรายเดียวในประเทศ','การไฟฟ้าที่ให้บริการสาธารณูปโภคแก่กิจการ'], a:0,
     e:'ข้อแรกอยู่ในรายการแปดข้อของกิจการที่เกี่ยวข้องกัน เป็นกรณีที่เกี่ยวกันผ่านบุคคลที่สามคนเดียวกัน แม้สองกิจการนั้นจะไม่ได้เกี่ยวกันเองเลย · ส่วนอีกสามข้อมาตรฐานระบุชัดว่าไม่ใช่ RP เพราะเป็นความสัมพันธ์ทางธุรกิจตามปกติ ไม่ใช่ความสัมพันธ์เชิงอำนาจ'},
"""

TOTAL = QUIZ2.count(u'{ch:')
